item.command:
/bin/zsh -lc "node --input-type=module <<'RELAYER_GRAPH_PROGRAM'
import {
  RelayerGraphClient,
  NodeObject,
  EdgeObject,
  NodePlacementObject,
  LayerLayoutObject,
  LayerObject,
  html,
  css,
  detailCapability,
} from 'file:///Users/[redacted]/.codex/worktrees/attached-navigation/relayer-graphcomplete/packages/graph-client/dist/index.js';

const graph = RelayerGraphClient.fromEnv();
const interactionNode = 21;

await graph.getNode(interactionNode);
await graph.getNeighbors(interactionNode);
let current = await graph.getCurrent();

const launchDecision = new NodeObject(
  'info',
  'Launch decision',
  'Release when error rate stays below 1% and rollback is ready.',
  'check-circle',
  'launch-decision',
);
const evidenceShelf = new NodeObject(
  'info',
  'Evidence shelf',
  'Open the synthetic baseline used to rehearse the release gate.',
  'archive',
  'evidence-shelf',
);
const trafficBaseline = new NodeObject(
  'info',
  'Traffic baseline',
  'Synthetic walkthrough context only: verify the error-rate gate and rollback readiness before release.',
  'bar-chart-3',
  'traffic-baseline',
);

const rootEdge = new EdgeObject([launchDecision, evidenceShelf], 'launch-evidence-edge');
const baselineEdge = new EdgeObject([launchDecision, trafficBaseline], 'launch-baseline-edge');

const rootLayout = new LayerLayoutObject([
  new NodePlacementObject(launchDecision, 0.30, 0.50),
  new NodePlacementObject(evidenceShelf, 0.72, 0.50),
]);
const baselineLayout = new LayerLayoutObject([
  new NodePlacementObject(launchDecision, 0.30, 0.50),
  new NodePlacementObject(trafficBaseline, 0.72, 0.50),
]);

const rootLayer = new LayerObject(
  [launchDecision, evidenceShelf],
  [rootEdge],
  rootLayout,
  'release-readiness-root',
);
rootLayer.defaultNode = launchDecision;

const baselineLayer = new LayerObject(
  [launchDecision, trafficBaseline],
  [baselineEdge],
  baselineLayout,
  'baseline-inspection-layer',
);
baselineLayer.defaultNode = launchDecision;

const rolloutInvoke = {
  kind: 'invoke',
  sourceLayer: rootLayer,
  label: 'Draft rollout recommendation',
  interactionText: 'Draft a rollout recommendation for this release-readiness walkthrough.',
  icon: 'pencil-line',
  variant: 'wide',
  clientKey: 'draft-rollout-recommendation',
};
const inspectBaseline = {
  kind: 'navigate',
  relation: 'expand',
  sourceLayer: rootLayer,
  label: 'Inspect baseline',
  target: baselineLayer,
  icon: 'bar-chart-3',
  variant: 'wide',
  clientKey: 'inspect-baseline',
};

const actionBinder = typeof detailCapability.action === 'function'
  ? (action) => detailCapability.action(action)
  : typeof detailCapability === 'function'
    ? (action) => detailCapability(action)
    : (action) => detailCapability.invoke(action);

let backReference = null;
if (current?.currentLayerId) {
  backReference = {
    kind: 'navigate',
    relation: 'reference',
    sourceLayer: rootLayer,
    label: 'View prior context',
    target: current.currentLayerId,
    icon: 'arrow-right-left',
    variant: 'pill',
    clientKey: 'release-readiness-prior-context',
  };
}

launchDecision.detailAuthoring.setComponent(
  'main',
  html"'`<main class="decision-card">
    <div class="eyebrow">Synthetic release gate</div>
    <h2>Launch decision</h2>
    <p class="decision">Release when error rate stays below <strong>1%</strong> and rollback is ready.</p>
    <div class="gate-row" aria-label="Release criteria">
      <span class="gate"><b>&lt; 1%</b><small>Error rate</small></span>
      <span class="join">and</span>
      <span class="gate"><b>Ready</b><small>Rollback</small></span>
    </div>
    <button class="primary" ${actionBinder(rolloutInvoke)}>Draft rollout recommendation</button>
  </main>`,
  css`
    .decision-card { display: grid; gap: 1rem; padding: 1.4rem; border: 1px solid; border-radius: 1rem; max-width: 42rem; box-sizing: border-box; }
    .eyebrow { font-size: 0.75rem; font-weight: 700; letter-spacing: 0.08rem; text-transform: uppercase; }
    h2 { margin: 0; font-size: 1.45rem; line-height: 1.2; }
    .decision { margin: 0; font-size: 1.05rem; line-height: 1.6; }
    .gate-row { display: grid; grid-template-columns: 1fr auto 1fr; gap: 0.65rem; align-items: center; }
    .gate { display: grid; gap: 0.2rem; padding: 0.8rem; border: 1px solid; border-radius: 0.75rem; text-align: center; }
    .gate b { font-size: 1rem; }
    .gate small { font-size: 0.74rem; }
    .join { font-size: 0.78rem; font-weight: 700; text-transform: uppercase; }
    .primary { width: 100%; padding: 0.8rem 1rem; border: 1px solid; border-radius: 0.65rem; font: inherit; font-weight: 700; }
    .primary:hover { opacity: 0.88; }
    .primary:focus-visible { outline: 3px solid; outline-offset: 2px; }
    [data-relayer-theme="light"] .decision-card { color: #17202a; background-color: #fbfcfe; border-color: #d9e0e7; box-shadow: 0 8px 24px rgba(25, 38, 52, 0.08); }
    [data-relayer-theme="light"] .eyebrow { color: #52606d; }
    [data-relayer-theme="light"] .gate { background-color: #f2f7f5; border-color: #b8d4c6; }
    [data-relayer-theme="light"] .gate small, [data-relayer-theme="light"] .join { color: #58656f; }
    [data-relayer-theme="light"] .primary { color: #ffffff; background-color: #175f4c; border-color: #175f4c; }
    [data-relayer-theme="light"] .primary:focus-visible { outline-color: #0b6bcb; }
    [data-relayer-theme="dark"] .decision-card { color: #edf3f5; background-color: #141a1d; border-color: #344248; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.28); }
    [data-relayer-theme="dark"] .eyebrow { color: #a9b7bd; }
    [data-relayer-theme="dark"] .gate { background-color: #192622; border-color: #3e6b5d; }
    [data-relayer-theme="dark"] .gate small, [data-relayer-theme="dark"] .join { color: #afbdc2; }
    [data-relayer-theme="dark"] .primary { color: #0d201a; background-color: #8fd5ba; border-color: #8fd5ba; }
    [data-relayer-theme="dark"] .primary:focus-visible { outline-color: #76bfff; }
  `,
);

const evidenceControls = backReference
  ? html`<div class="controls"><button class="primary" ${actionBinder(inspectBaseline)}>Inspect baseline</button><button class="secondary" ${actionBinder(backReference)}>View prior context</button></div>`
  : html`<div class="controls"><button class="primary" ${actionBinder(inspectBaseline)}>Inspect baseline</button></div>`;

evidenceShelf.detailAuthoring.setComponent(
  '"'main',
  html"'`<main class="shelf-card">
    <div class="eyebrow">Supporting view</div>
    <h2>Evidence shelf</h2>
    <p>Open the compact synthetic baseline to inspect how the decision gate is framed. No customer data is used.</p>
    ${evidenceControls}
  </main>`,
  css`
    .shelf-card { display: grid; gap: 1rem; padding: 1.4rem; border: 1px solid; border-radius: 1rem; max-width: 42rem; box-sizing: border-box; }
    .eyebrow { font-size: 0.75rem; font-weight: 700; letter-spacing: 0.08rem; text-transform: uppercase; }
    h2 { margin: 0; font-size: 1.45rem; line-height: 1.2; }
    p { margin: 0; line-height: 1.6; }
    .controls { display: grid; gap: 0.65rem; }
    button { width: 100%; padding: 0.8rem 1rem; border: 1px solid; border-radius: 0.65rem; font: inherit; font-weight: 700; }
    button:hover { opacity: 0.88; }
    button:focus-visible { outline: 3px solid; outline-offset: 2px; }
    [data-relayer-theme="light"] .shelf-card { color: #17202a; background-color: #fbfcfe; border-color: #d9e0e7; box-shadow: 0 8px 24px rgba(25, 38, 52, 0.08); }
    [data-relayer-theme="light"] .eyebrow { color: #52606d; }
    [data-relayer-theme="light"] .primary { color: #ffffff; background-color: #315c7d; border-color: #315c7d; }
    [data-relayer-theme="light"] .secondary { color: #243746; background-color: #eef3f7; border-color: #bdcbd5; }
    [data-relayer-theme="light"] button:focus-visible { outline-color: #0b6bcb; }
    [data-relayer-theme="dark"] .shelf-card { color: #edf3f5; background-color: #141a1d; border-color: #344248; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.28); }
    [data-relayer-theme="dark"] .eyebrow { color: #a9b7bd; }
    [data-relayer-theme="dark"] .primary { color: #10202b; background-color: #9cc7e4; border-color: #9cc7e4; }
    [data-relayer-theme="dark"] .secondary { color: #e5edf1; background-color: #222d32; border-color: #526269; }
    [data-relayer-theme="dark"] button:focus-visible { outline-color: #76bfff; }
  `,
);

trafficBaseline.detailAuthoring.setComponent(
  '"'main',
  html"'`<main class="baseline-card">
    <div class="eyebrow">Synthetic baseline</div>
    <h2>Traffic baseline</h2>
    <p>This fixture supplies no measured traffic or customer facts. It keeps the walkthrough focused on the two release checks.</p>
    <dl>
      <div><dt>Error-rate gate</dt><dd>Must stay below 1%</dd></div>
      <div><dt>Recovery gate</dt><dd>Rollback must be ready</dd></div>
    </dl>
  </main>`,
  css`
    .baseline-card { display: grid; gap: 1rem; padding: 1.4rem; border: 1px solid; border-radius: 1rem; max-width: 42rem; box-sizing: border-box; }
    .eyebrow { font-size: 0.75rem; font-weight: 700; letter-spacing: 0.08rem; text-transform: uppercase; }
    h2 { margin: 0; font-size: 1.45rem; line-height: 1.2; }
    p { margin: 0; line-height: 1.6; }
    dl { display: grid; gap: 0.65rem; margin: 0; }
    dl div { display: grid; grid-template-columns: 1fr 1.2fr; gap: 0.8rem; padding: 0.75rem; border: 1px solid; border-radius: 0.7rem; }
    dt { font-weight: 700; }
    dd { margin: 0; }
    [data-relayer-theme="light"] .baseline-card { color: #17202a; background-color: #fbfcfe; border-color: #d9e0e7; box-shadow: 0 8px 24px rgba(25, 38, 52, 0.08); }
    [data-relayer-theme="light"] .eyebrow { color: #52606d; }
    [data-relayer-theme="light"] dl div { background-color: #f5f7f9; border-color: #d5dde4; }
    [data-relayer-theme="dark"] .baseline-card { color: #edf3f5; background-color: #141a1d; border-color: #344248; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.28); }
    [data-relayer-theme="dark"] .eyebrow { color: #a9b7bd; }
    [data-relayer-theme="dark"] dl div { background-color: #1d2529; border-color: #3d4b51; }
  `,
);

await graph.checkpointNodeDetail(launchDecision);
await graph.checkpointNodeDetail(evidenceShelf);
await graph.checkpointNodeDetail(trafficBaseline);

await graph.submitNode(launchDecision);
await graph.submitNode(evidenceShelf);
await graph.submitNode(trafficBaseline);
await graph.submitEdge(rootEdge);
await graph.submitEdge(baselineEdge);
await graph.submitLayer(baselineLayer);
await graph.submitLayer(rootLayer);

await graph.addAction(launchDecision, rolloutInvoke);
await graph.addAction(evidenceShelf, inspectBaseline);
if (backReference) await graph.addAction(evidenceShelf, backReference);
await graph.addAction(interactionNode, {
  kind: '"'navigate',
  relation: 'expand',
  label: 'Open release readiness',
  target: rootLayer,
  clientKey: 'release-readiness-response',
});

if (current && Number.isSafeInteger(current.headRevision)) {
  await graph.advanceCurrent(rootLayer, current.headRevision, 'publish-release-readiness-root');
}

await graph.submit(interactionNode);
RELAYER_GRAPH_PROGRAM"

