async createEdge(leftOrEdge, right, clientKey = randomUUID()) {
        const edge = leftOrEdge instanceof EdgeObject ? leftOrEdge : new EdgeObject([leftOrEdge, requireReference(right)], clientKey);
        const body = await this.request("/api/graph/edges", {
            method: "POST",
            body: JSON.stringify({ clientKey: edge.clientKey, endpoints: edge.endpoints.map(nodeId) }),
        });
        edge.ref = body.edge;
        return body.edge;
    }
async createEdges(pairs) {
        const edges = [];
        for (const pair of pairs)
            edges.push(await this.createEdge(pair[0], pair[1]));
        return edges;
    }

