const graph = RelayerGraphClient.fromEnv();
const interactionNode = 21;
await graph.getNode(interactionNode);
await graph.getNeighbors(interactionNode);
const launchDecision = new NodeObject('info', 'Launch decision', 'Release when error rate stays below 1% and rollback is ready.', 'check-circle', 'launch-decision');
const evidenceShelf = new NodeObject('info', 'Evidence shelf', 'Open the synthetic baseline used to rehearse the release gate.', 'archive', 'evidence-shelf');
