const baselineEdge = new EdgeObject([launchDecision, trafficBaseline], 'launch-baseline-edge');
const rootLayer = new LayerObject([launchDecision, evidenceShelf], [rootEdge], new LayerLayoutObject([
  new NodePlacementObject(launchDecision, 0.30, 0.50), new NodePlacementObject(evidenceShelf, 0.72, 0.50),
]), 'release-readiness-root');
rootLayer.defaultNode = launchDecision;
const baselineLayer = new LayerObject([launchDecision, trafficBaseline], [baselineEdge], new LayerLayoutObject([
  new NodePlacementObject(launchDecision, 0.30, 0.50), new NodePlacementObject(trafficBaseline, 0.72, 0.50),
]), 'baseline-inspection-layer');
baselineLayer.defaultNode = launchDecision;
