  dt { font-weight: 700; } dd { margin: 0; }
  [data-relayer-theme="light"] .card { color: #17202a; background-color: #fbfcfe; border-color: #d9e0e7; box-shadow: 0 8px 24px rgba(25, 38, 52, 0.08); }
  [data-relayer-theme="light"] .eyebrow { color: #52606d; } [data-relayer-theme="light"] .gate { background-color: #f2f7f5; border-color: #b8d4c6; }
  [data-relayer-theme="light"] dl div { background-color: #f5f7f9; border-color: #d5dde4; } [data-relayer-theme="light"] .primary { color: #ffffff; background-color: #245f70; border-color: #245f70; }
  [data-relayer-theme="light"] .primary:focus-visible { outline-color: #0b6bcb; }
  [data-relayer-theme="dark"] .card { color: #edf3f5; background-color: #141a1d; border-color: #344248; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.28); }
  [data-relayer-theme="dark"] .eyebrow { color: #a9b7bd; } [data-relayer-theme="dark"] .gate { background-color: #192622; border-color: #3e6b5d; }
  [data-relayer-theme="dark"] dl div { background-color: #1d2529; border-color: #3d4b51; } [data-relayer-theme="dark"] .primary { color: #10202b; background-color: #9fd3d6; border-color: #9fd3d6; }
  [data-relayer-theme="dark"] .primary:focus-visible { outline-color: #76bfff; }
`;
launchDecision.detailAuthoring.setComponent('"'main', html"'`<main class="card"><div class="eyebrow">Synthetic release gate</div><h2>Launch decision</h2><p>Release when error rate stays below <strong>1%</strong> and rollback is ready.</p><div class="gate-row" aria-label="Release criteria"><span class="gate"><b>&lt; 1%</b><small>Error rate</small></span><span class="join">and</span><span class="gate"><b>Ready</b><small>Rollback</small></span></div><button class="primary" gc=${detailCapability.invoke('"'launch-rollout-control', rolloutInvoke)}>Draft rollout recommendation</button></main>"'`, sharedCss);
evidenceShelf.detailAuthoring.setComponent('"'main', html"'`<main class="card"><div class="eyebrow">Supporting view</div><h2>Evidence shelf</h2><p>Open the compact synthetic baseline to inspect how the decision gate is framed. No customer data is used.</p><button class="primary" gc=${detailCapability.expand('"'inspect-baseline-control', inspectBaseline)}>Inspect baseline</button></main>"'`, sharedCss);
trafficBaseline.detailAuthoring.setComponent('"'main', html"'`<main class="card"><div class="eyebrow">Synthetic baseline</div><h2>Traffic baseline</h2><p>This fixture supplies no measured traffic or customer facts. It keeps the walkthrough focused on the two release checks.</p><dl><div><dt>Error-rate gate</dt><dd>Must stay below 1%</dd></div><div><dt>Recovery gate</dt><dd>Rollback must be ready</dd></div></dl></main>`, sharedCss);
await graph.checkpointNodeDetail(launchDecision);
await graph.checkpointNodeDetail(evidenceShelf);
await graph.checkpointNodeDetail(trafficBaseline);
await graph.submitNode(launchDecision);
await graph.submitNode(evidenceShelf);
await graph.submitNode(trafficBaseline);
await graph.createEdge(rootEdge);
await graph.createEdge(baselineEdge);
await graph.submitLayer(baselineLayer);
await graph.submitLayer(rootLayer);
await graph.addAction(launchDecision, rolloutInvoke);
await graph.addAction(evidenceShelf, inspectBaseline);
await graph.addAction(interactionNode, { kind: '"'navigate', relation: 'expand', label: 'Open release readiness', target: rootLayer, clientKey: 'release-readiness-response' });
await graph.submit(interactionNode);
RELAYER_GRAPH_PROGRAM"

